{
  "id": "com.example.hello",
  "version": "1.1.0",
  "name": "Hello Circle",
  "description": "Adds a circle (v1.1 adds an adjustable radius via storage).",
  "publisher": "Example Co.",
  "engines": { "sketchor": "^0.3.0" },
  "main": "plugin.js",
  "contributes": {
    "commands": [{ "id": "hello.circle", "title": "Hello: add a circle (v1.1)" }]
  },
  "permissions": ["read-document", "write-document", "storage"]
}

code:
export default {
  activate(sketchor) {
    sketchor.commands.register("hello.circle", async () => {
      const r = Number(await sketchor.storage.get("radius")) || 20;
      const id = "hp" + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36);
      sketchor.document.apply([
        { type: "add-entity", entity: { id, type: "circle", center: { x: 0, y: 0 }, radius: r } },
      ]);
      sketchor.ui.notify("Hello Circle v1.1 added a circle r=" + r);
    });
  },
};
